;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;
;  RobboNext - binary assets
;
;  Large data lives in 8K pages that are mapped at 0x2000 when needed
;  (page numbers must match hw.h). Generated by scripts/convert_assets.py,
;  except the font.
;
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;

; 56 levels x 512 bytes, 16 levels per page (pages 42-45)
SECTION PAGE_42_LEVELS
ORG $0000
    INCBIN "res/levels.bin"

; board tiles and animation frames, 16x16 at 8 bits per pixel stored
; column by column, 32 per page
SECTION PAGE_48_TILES
ORG $0000
    INCBIN "res/tiles.bin"

; 8-bit sprite patterns, one set per screen
SECTION PAGE_53_SPR_GAME
ORG $0000
    INCBIN "res/spr_game.bin"

SECTION PAGE_54_SPR_TITLE
ORG $0000
    INCBIN "res/spr_title.bin"

SECTION PAGE_55_SPR_ENDING
ORG $0000
    INCBIN "res/spr_ending.bin"

; status bar digits and the tilemap font (offsets in hw.h)
SECTION PAGE_56_MISC
ORG $0000
    INCBIN "res/digits.bin"             ; 0
    INCBIN "res/tm_font.bin"            ; 1280
    INCBIN "res/splash.npl"             ; 4352: opening picture palette

; 320x256 pictures, column by column, 10 pages each (in two sections of 5)
SECTION PAGE_57_TITLE_PIC
ORG $0000
    INCBIN "res/title_a.bin"

SECTION PAGE_62_TITLE_PIC
ORG $0000
    INCBIN "res/title_b.bin"

SECTION PAGE_67_ENDING_PIC
ORG $0000
    INCBIN "res/ending_a.bin"

SECTION PAGE_72_ENDING_PIC
ORG $0000
    INCBIN "res/ending_b.bin"

; opening picture (art/splash), with its own palette in PAGE_56_MISC
SECTION PAGE_77_SPLASH_PIC
ORG $0000
    INCBIN "res/splash_a.bin"

SECTION PAGE_82_SPLASH_PIC
ORG $0000
    INCBIN "res/splash_b.bin"

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;

; resident page, mapped at 0x0000 for the whole game (the ROM is never used)

SECTION PAGE_46_RESIDENT
ORG $0000

PUBLIC _font_data
PUBLIC _ramp_data
PUBLIC _sound_data

_font_data:
    INCBIN "res/font.bin"       ; ZX Spectrum ROM font, characters 32-127

_ramp_data:
    INCBIN "res/ramps.bin"      ; 48 colours x 8 shades x 2 bytes

_sound_data:
    INCBIN "res/sound.bin"

; constant tables and texts of data.c (compiled with --constseg)
SECTION PAGE_46_RESIDENT_C
ORG $1000

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;

; page 47, mapped at 0x6000 for the whole game: code compiled with
; --codeseg=PAGE_47_CODE (title screen, ending, particles)

SECTION PAGE_47_CODE
ORG $6000
